46	/* 3x3 same padding, stride 1, +ReLU. w 布局 (kh,kw,in,out), b[out] */
47	static void conv3x3_same_relu(const float *in, int H, int W, int Cin,
48	                              const float *w, const float *b, int Cout,
49	                              float *out) {
50	  for (int o = 0; o < Cout; ++o) {
51	    for (int h = 0; h < H; ++h) {
52	      for (int p = 0; p < W; ++p) {
53	        float acc = b[o];
54	        for (int kh = 0; kh < 3; ++kh) {
55	          int ih = h + kh - 1;
56	          if (ih < 0 || ih >= H) continue;
57	          for (int kw = 0; kw < 3; ++kw) {
58	            int iw = p + kw - 1;
59	            if (iw < 0 || iw >= W) continue;
60	            const float *ip = in + ((ih * W) + iw) * Cin;
61	            for (int c = 0; c < Cin; ++c)
62	              acc += ip[c] * w[(((kh * 3) + kw) * Cin + c) * Cout + o];
63	          }
64	        }
65	        out[((h * W) + p) * Cout + o] = acc > 0 ? acc : 0;
66	      }
67	    }
68	  }
69	}
