71	/* 2x2 max pool, stride 2, valid */
72	static void maxpool2(const float *in, int H, int W, int C, float *out,
73	                     int *oH, int *oW) {
74	  *oH = H / 2;
75	  *oW = W / 2;
76	  for (int h = 0; h < *oH; ++h)
77	    for (int w = 0; w < *oW; ++w)
78	      for (int c = 0; c < C; ++c) {
79	        float m = in[((2 * h) * W + (2 * w)) * C + c];
80	        float t;
81	        t = in[((2 * h) * W + (2 * w + 1)) * C + c];
82	        if (t > m) m = t;
83	        t = in[((2 * h + 1) * W + (2 * w)) * C + c];
84	        if (t > m) m = t;
85	        t = in[((2 * h + 1) * W + (2 * w + 1)) * C + c];
86	        if (t > m) m = t;
87	        out[((h * (*oW)) + w) * C + c] = m;
88	      }
89	}
