91	/* 全局平均池化 */
92	static void gap(const float *in, int H, int W, int C, float *out) {
93	  for (int c = 0; c < C; ++c) {
94	    float s = 0;
95	    for (int i = 0; i < H * W; ++i) s += in[i * C + c];
96	    out[c] = s / (H * W);
97	  }
98	}
99	
100	/* dense + ReLU. w 布局 (in,out) */
101	static void dense_relu(const float *in, int Din, const float *w,
102	                       const float *b, int Dout, float *out) {
103	  for (int o = 0; o < Dout; ++o) {
104	    float acc = b[o];
105	    for (int i = 0; i < Din; ++i) acc += in[i] * w[i * Dout + o];
106	    out[o] = acc > 0 ? acc : 0;
107	  }
108	}
109	
110	/* dense + softmax */
111	static void dense_softmax(const float *in, int Din, const float *w,
112	                          const float *b, int Dout, float *out) {
113	  float mx = -1e30f;
114	  for (int o = 0; o < Dout; ++o) {
115	    float acc = b[o];
116	    for (int i = 0; i < Din; ++i) acc += in[i] * w[i * Dout + o];
117	    out[o] = acc;
118	    if (acc > mx) mx = acc;
119	  }
120	  float s = 0;
121	  for (int o = 0; o < Dout; ++o) {
122	    out[o] = expf(out[o] - mx);
123	    s += out[o];
124	  }
125	  for (int o = 0; o < Dout; ++o) out[o] /= s;
126	}
127	
128	/* mel: [49*40] float -> prob: [3] */
129	static void predict(const float *mel, float *prob) {
130	  conv3x3_same_relu(mel, MEL_NFRAMES, MEL_NMELS, CONV1_IN, conv1_w, conv1_b,
131	                    CONV1_OUT, buf_conv1);
132	  int H, W;
133	  maxpool2(buf_conv1, MEL_NFRAMES, MEL_NMELS, CONV1_OUT, buf_pool1, &H, &W);
134	  conv3x3_same_relu(buf_pool1, H, W, CONV2_IN, conv2_w, conv2_b, CONV2_OUT,
135	                    buf_conv2);
136	  maxpool2(buf_conv2, H, W, CONV2_OUT, buf_pool2, &H, &W);
137	  conv3x3_same_relu(buf_pool2, H, W, CONV3_IN, conv3_w, conv3_b, CONV3_OUT,
138	                    buf_conv3);
139	  gap(buf_conv3, H, W, CONV3_OUT, buf_gap);
140	  dense_relu(buf_gap, CONV3_OUT, dense1_w, dense1_b, DENSE1_OUT, buf_d1);
141	  dense_softmax(buf_d1, DENSE1_OUT, dense2_w, dense2_b, DENSE2_OUT, prob);
142	}
