144	/* 读 raw PCM 文件 (16k/mono/16bit, 无文件头) -> float[-1,1], 返回样本数 */
145	static int read_pcm(const char *path, float **out_samples) {
146	  FILE *fp = fopen(path, "rb");
147	  if (!fp) {
148	    syslog(LOG_INFO, "无法打开 %s\n", path);
149	    return -1;
150	  }
151	  fseek(fp, 0, SEEK_END);
152	  long bytes = ftell(fp);
153	  fseek(fp, 0, SEEK_SET);
154	  if (bytes <= 0) {
155	    syslog(LOG_INFO, "文件为空: %s\n", path);
156	    fclose(fp);
157	    return -1;
158	  }
159	  size_t n = bytes / 2;            /* 16bit -> 每样本 2 字节 */
160	  int16_t *raw = malloc(n * 2);
161	  size_t got = fread(raw, 2, n, fp);
162	  fclose(fp);
163	  float *s = malloc(got * sizeof(float));
164	  for (size_t i = 0; i < got; ++i) s[i] = raw[i] / 32768.0f;
165	  free(raw);
166	  *out_samples = s;
167	  return (int)got;
168	}
169	
170	/* 模式一: 从 raw PCM 文件离线检测 */
171	static int run_from_file(const char *path) {
172	  float *samples = NULL;
173	  int n = read_pcm(path, &samples);
174	  if (n < MEL_SR) {
175	    syslog(LOG_INFO, "样本太少: %d\n", n);
176	    return 1;
177	  }
178	  syslog(LOG_INFO, "pcm: %s  样本=%d  时长=%.2fs (16k/mono/16bit)\n",
179	         path, n, (double)n / MEL_SR);
180	
181	  mel_init();
182	  const int hop = WAKE_HOP_SAMPLES;
183	  const int nwin = 1 + (n - MEL_SR) / hop;
184	  const int smooth = 5;
185	  const int min_dist = (int)(1.2f * MEL_SR / hop);
186	
187	  float *prob = malloc(nwin * sizeof(float));
188	  static float mel[MEL_NFRAMES * MEL_NMELS];
189	  float p3[3];
190	  for (int i = 0; i < nwin; ++i) {
191	    mel_compute(samples + i * hop, mel);
192	    predict(mel, p3);
193	    prob[i] = p3[0];
194	  }
195	
196	  /* 滑动平均 */
197	  float *sm = malloc(nwin * sizeof(float));
198	  for (int i = 0; i < nwin; ++i) {
199	    float s = 0;
200	    int c = 0;
201	    for (int d = -smooth / 2; d <= smooth / 2; ++d) {
202	      int j = i + d;
203	      if (j >= 0 && j < nwin) {
204	        s += prob[j];
205	        ++c;
206	      }
207	    }
208	    sm[i] = s / c;
209	  }
210	
211	  /* 峰值检测: 先收集, 再打印 */
212	  int *peaks = malloc(nwin * sizeof(int));
213	  int np = 0;
214	  for (int i = 1; i < nwin - 1; ++i) {
215	    if (sm[i] >= WAKE_THR && sm[i] >= sm[i - 1] && sm[i] >= sm[i + 1]) {
216	      if (np == 0 || (i - peaks[np - 1]) >= min_dist) {
217	        peaks[np++] = i;
218	      } else if (sm[i] > sm[peaks[np - 1]]) {
219	        peaks[np - 1] = i;
220	      }
221	    }
222	  }
223	  syslog(LOG_INFO, "\n检测到 %d 个唤醒事件 (阈值 %.2f, 最小间隔 1.2s):\n", np, (double)WAKE_THR);
224	  for (int k = 0; k < np; ++k) {
225	    float t = (float)peaks[k] * hop / MEL_SR;
226	    syslog(LOG_INFO, "  %6.2fs  target_prob=%.3f\n", (double)t, (double)sm[peaks[k]]);
227	  }
228	
229	  free(peaks);
230	  free(prob);
231	  free(sm);
232	  free(samples);
233	  return 0;
234	}
235	
236	/* 模式二: 从麦克风实时采集检测 (参考 nxrecorder, /dev/audio/pcm0c, 16k/16bit/1ch)。
237	 * duration<=0 表示不限时, 直到 Ctrl-C (SIGINT) 停止。 */
238	static struct mic_capture_s *g_cap = NULL;
239	static void on_sigint(int sig) {
240	  (void)sig;
241	  if (g_cap) g_cap->running = 0;   /* 唤醒 mic_capture_read 退出 */
242	}
243	
244	static int run_from_mic(const char *device, int duration) {
245	  struct mic_capture_s cap;
246	  int ret = mic_capture_start(&cap, device, MEL_SR, 1, 16);
247	  if (ret != 0) {
248	    syslog(LOG_INFO, "mic_capture_start 失败: %d\n", ret);
249	    return 1;
250	  }
251	  g_cap = &cap;
252	  signal(SIGINT, on_sigint);
253	  if (duration > 0)
254	    syslog(LOG_INFO, "录音中 %ds, 唤醒条件: 连续%d窗 prob>%.2f\n",
255	           duration, WAKE_CONSEC, (double)WAKE_THR);
256	  else
257	    syslog(LOG_INFO, "录音中 (不限时, Ctrl-C 停止), 唤醒条件: 连续%d窗 prob>%.2f\n",
258	           WAKE_CONSEC, (double)WAKE_THR);
259	
260	  mel_init();
261	  static float window[MEL_SR];
262	  static int16_t hopbuf[WAKE_HOP_SAMPLES];
263	  static float mel[MEL_NFRAMES * MEL_NMELS];
264	  float p3[3];
265	  memset(window, 0, sizeof(window));
266	
267	  int nframes = (duration > 0) ? (duration * 1000 / 100) : -1;  /* <=0 表示不限时 */
268	  int last_wake = -WAKE_MIN_DIST;
269	  int consec = 0;   /* 当前连续超阈窗数 */
270	  int wakes = 0;
271	  int f;
272	
273	  for (f = 0; nframes < 0 || f < nframes; ++f) {
274	    if (mic_capture_read(&cap, hopbuf, WAKE_HOP_SAMPLES) != 0)
275	      break;   /* Ctrl-C 或停止 */
276	    /* 滑动窗口左移 hop, 末尾追加新数据 */
277	    memmove(window, window + WAKE_HOP_SAMPLES,
278	            (MEL_SR - WAKE_HOP_SAMPLES) * sizeof(float));
279	    for (int i = 0; i < WAKE_HOP_SAMPLES; ++i)
280	      window[MEL_SR - WAKE_HOP_SAMPLES + i] = hopbuf[i] / 32768.0f;
281	
282	    mel_compute(window, mel);
283	    predict(mel, p3);
284	    float prob = p3[0];
285	    float t = (float)f * 0.1f;
286	    /* 连续 WAKE_CONSEC 窗超阈才判唤醒: 误报多为孤立单窗尖峰,
287	     * 真唤醒词会连续 10+ 窗超阈。 */
288	    if (prob > WAKE_THR) ++consec; else consec = 0;
289	    if (consec >= WAKE_CONSEC && (f - last_wake) >= WAKE_MIN_DIST) {
290	      syslog(LOG_INFO, "[%6.2fs] *** 唤醒 *** stone112 target_prob=%.3f\n",
291	             (double)t, (double)prob);
292	      last_wake = f;
293	      consec = 0;
294	      ++wakes;
295	    } else {
296	      syslog(LOG_INFO, "[%6.2fs] prob=%.3f\n", (double)t, (double)prob);
297	    }
298	  }
299	
300	  g_cap = NULL;
301	  mic_capture_stop(&cap);
302	  syslog(LOG_INFO, "结束, 共 %d 次唤醒\n", wakes);
303	  return 0;
304	}
305	
306	/* 判断字符串是否为纯数字 */
307	static int is_number(const char *s) {
308	  if (s == NULL || *s == '\0') return 0;
309	  for (const char *p = s; *p; ++p)
310	    if (*p < '0' || *p > '9') return 0;
311	  return 1;
312	}
313	
314	int main(int argc, char *argv[]) {
315	  if (argc >= 2 && argv[1][0] != '\0') {
316	    if (is_number(argv[1])) {
317	      /* 数字: 麦克风限时 N 秒 */
318	      return run_from_mic(WAKE_MIC_DEVICE, atoi(argv[1]));
319	    }
320	    /* 非数字: 文件路径 */
321	    return run_from_file(argv[1]);
322	  }
323	  /* 无参数: 麦克风不限时 */
324	  return run_from_mic(WAKE_MIC_DEVICE, 0);
325	}
