20	static void ring_push(struct mic_capture_s *c, const int16_t *data, int n)
21	{
22	  pthread_mutex_lock(&c->lock);
23	  for (int i = 0; i < n; ++i)
24	    {
25	      c->ring[c->wr] = data[i];
26	      c->wr = (c->wr + 1) % c->ring_size;
27	      if (c->count < c->ring_size)
28	        c->count++;
29	      else
30	        c->rd = (c->rd + 1) % c->ring_size;  /* 覆盖最旧 */
31	    }
32	  pthread_cond_signal(&c->cond);
33	  pthread_mutex_unlock(&c->lock);
34	}
35	
36	static int mic_enqueue(struct mic_capture_s *c, FAR struct ap_buffer_s *apb)
37	{
38	  struct audio_buf_desc_s buf_desc;
39	#ifdef CONFIG_AUDIO_MULTI_SESSION
40	  buf_desc.session = NULL;
41	#endif
42	  apb->nbytes  = apb->nmaxbytes;
43	  apb->flags   = 0;
44	  apb->curbyte = 0;
45	  buf_desc.numbytes  = apb->nbytes;
46	  buf_desc.u.buffer  = apb;
47	  return ioctl(c->dev_fd, AUDIOIOC_ENQUEUEBUFFER, (uintptr_t)&buf_desc);
48	}
49	
50	static FAR void *mic_thread(pthread_addr_t pvarg)
51	{
52	  FAR struct mic_capture_s *c = (FAR struct mic_capture_s *)pvarg;
53	  struct audio_msg_s msg;
54	  unsigned int prio;
55	
56	  while (c->running)
57	    {
58	      ssize_t size = mq_receive(c->mq, (FAR char *)&msg, sizeof(msg), &prio);
59	      if (size != sizeof(msg))
60	        continue;
61	
62	      switch (msg.msg_id)
63	        {
64	          case AUDIO_MSG_DEQUEUE:
65	            {
66	              FAR struct ap_buffer_s *apb =
67	                (FAR struct ap_buffer_s *)msg.u.ptr;
68	              if (apb && apb->nbytes > 0)
69	                {
70	                  int nsamp = apb->nbytes / 2;
71	                  ring_push(c, (const int16_t *)apb->samp, nsamp);
72	                }
73	              mic_enqueue(c, apb);
74	            }
75	            break;
76	
77	          case AUDIO_MSG_STOP:
78	          case AUDIO_MSG_COMPLETE:
79	            c->running = 0;
80	            pthread_cond_signal(&c->cond);
81	            goto done;
82	
83	          default:
84	            break;
85	        }
86	    }
87	done:
88	  return NULL;
89	}
