91	int mic_capture_start(struct mic_capture_s *c, const char *device,
92	                      int samplerate, int channels, int bps)
93	{
94	  struct audio_caps_desc_s cap_desc;
95	  struct ap_buffer_info_s  buf_info;
96	  struct mq_attr           attr;
97	  struct sched_param       sparam;
98	  pthread_attr_t           tattr;
99	  FAR struct ap_buffer_s  *pbuffers[16];
100	  int                      nbuffers;
101	  int                      ret;
102	  int                      x;
103	
104	  memset(c, 0, sizeof(*c));
105	  c->dev_fd = -1;
106	  c->mq = (mqd_t)-1;
107	  c->ring_size = MIC_RING_SAMPLES;
108	  c->ring = malloc(c->ring_size * sizeof(int16_t));
109	  if (c->ring == NULL)
110	    return -ENOMEM;
111	  pthread_mutex_init(&c->lock, NULL);
112	  pthread_cond_init(&c->cond, NULL);
113	
114	  c->dev_fd = open(device, O_RDWR | O_CLOEXEC);
115	  if (c->dev_fd < 0)
116	    {
117	      syslog(LOG_INFO, "打开 %s 失败: %d\n", device, -errno);
118	      return -errno;
119	    }
120	
121	#ifdef CONFIG_AUDIO_MULTI_SESSION
122	  cap_desc.session = NULL;
123	#endif
124	  memset(&cap_desc, 0, sizeof(cap_desc));
125	  cap_desc.caps.ac_type    = AUDIO_TYPE_INPUT;
126	  cap_desc.caps.ac_channels = channels;
127	  cap_desc.caps.ac_chmap   = 0;
128	  cap_desc.caps.ac_controls.hw[0] = samplerate;
129	  cap_desc.caps.ac_controls.b[3]  = samplerate >> 16;
130	  cap_desc.caps.ac_controls.b[2]  = bps;
131	  cap_desc.caps.ac_subtype = AUDIO_FMT_PCM;
132	  ret = ioctl(c->dev_fd, AUDIOIOC_CONFIGURE, (uintptr_t)&cap_desc);
133	  if (ret < 0)
134	    {
135	      syslog(LOG_INFO, "AUDIOIOC_CONFIGURE 失败: %d\n", -errno);
136	      return -errno;
137	    }
138	
139	  if (ioctl(c->dev_fd, AUDIOIOC_GETBUFFERINFO, (uintptr_t)&buf_info) != OK)
140	    {
141	      buf_info.buffer_size = CONFIG_AUDIO_BUFFER_NUMBYTES;
142	      buf_info.nbuffers    = CONFIG_AUDIO_NUM_BUFFERS;
143	    }
144	  nbuffers = buf_info.nbuffers;
145	  if (nbuffers > 16) nbuffers = 16;
146	
147	  attr.mq_maxmsg  = nbuffers + 8;
148	  attr.mq_msgsize = sizeof(struct audio_msg_s);
149	  attr.mq_curmsgs = 0;
150	  attr.mq_flags   = 0;
151	  snprintf(c->mqname, sizeof(c->mqname), "/tmp/%0lx",
152	           (unsigned long)(uintptr_t)c);
153	  c->mq = mq_open(c->mqname, O_RDWR | O_CREAT, 0644, &attr);
154	  if (c->mq == (mqd_t)-1)
155	    {
156	      syslog(LOG_INFO, "mq_open 失败: %d\n", -errno);
157	      return -errno;
158	    }
159	  ioctl(c->dev_fd, AUDIOIOC_REGISTERMQ, (uintptr_t)c->mq);
160	
161	  for (x = 0; x < nbuffers; ++x)
162	    {
163	      struct audio_buf_desc_s buf_desc;
164	#ifdef CONFIG_AUDIO_MULTI_SESSION
165	      buf_desc.session = NULL;
166	#endif
167	      buf_desc.numbytes = buf_info.buffer_size;
168	      buf_desc.u.pbuffer = &pbuffers[x];
169	      ret = ioctl(c->dev_fd, AUDIOIOC_ALLOCBUFFER, (uintptr_t)&buf_desc);
170	      if (ret != sizeof(buf_desc))
171	        {
172	          syslog(LOG_INFO, "ALLOCBUFFER %d 失败\n", x);
173	          return -EIO;
174	        }
175	    }
176	  for (x = 0; x < nbuffers; ++x)
177	    mic_enqueue(c, pbuffers[x]);
178	
179	  ret = ioctl(c->dev_fd, AUDIOIOC_START, 0);
180	  if (ret < 0)
181	    {
182	      syslog(LOG_INFO, "AUDIOIOC_START 失败: %d\n", -errno);
183	      return -errno;
184	    }
185	
186	  c->running = 1;
187	  pthread_attr_init(&tattr);
188	  sparam.sched_priority = sched_get_priority_max(SCHED_FIFO) - 9;
189	  pthread_attr_setschedparam(&tattr, &sparam);
190	  pthread_attr_setstacksize(&tattr, 8192);
191	  ret = pthread_create(&c->thread, &tattr, mic_thread, c);
192	  if (ret != 0)
193	    {
194	      syslog(LOG_INFO, "pthread_create 失败: %d\n", ret);
195	      c->running = 0;
196	      ioctl(c->dev_fd, AUDIOIOC_STOP, 0);
197	      return -ret;
198	    }
199	
200	  syslog(LOG_INFO, "采集已启动: %s %dHz %dch %dbit\n",
201	         device, samplerate, channels, bps);
202	  return 0;
203	}
204	
205	int mic_capture_read(struct mic_capture_s *c, int16_t *out, int nsamples)
206	{
207	  pthread_mutex_lock(&c->lock);
208	  while (c->running && c->count < nsamples)
209	    pthread_cond_wait(&c->cond, &c->lock);
210	  if (c->count < nsamples)
211	    {
212	      pthread_mutex_unlock(&c->lock);
213	      return -1;
214	    }
215	  for (int i = 0; i < nsamples; ++i)
216	    {
217	      out[i] = c->ring[c->rd];
218	      c->rd = (c->rd + 1) % c->ring_size;
219	    }
220	  c->count -= nsamples;
221	  pthread_mutex_unlock(&c->lock);
222	  return 0;
223	}
224	
225	void mic_capture_stop(struct mic_capture_s *c)
226	{
227	  if (c->running)
228	    {
229	      c->running = 0;
230	      ioctl(c->dev_fd, AUDIOIOC_STOP, 0);
231	      struct audio_msg_s msg;
232	      msg.msg_id = AUDIO_MSG_STOP;
233	      msg.u.ptr = NULL;
234	      mq_send(c->mq, (const char *)&msg, sizeof(msg), 0);
235	      pthread_cond_signal(&c->cond);
236	      pthread_join(c->thread, NULL);
237	    }
238	  if (c->dev_fd >= 0)
239	    {
240	      ioctl(c->dev_fd, AUDIOIOC_RELEASE, 0);
241	      close(c->dev_fd);
242	      c->dev_fd = -1;
243	    }
244	  if (c->mq != (mqd_t)-1)
245	    {
246	      mq_close(c->mq);
247	      mq_unlink(c->mqname);
248	      c->mq = (mqd_t)-1;
249	    }
250	  if (c->ring)
251	    {
252	      free(c->ring);
253	      c->ring = NULL;
254	    }
255	}
