91	static void action_click_cb(lv_event_t *event)
92	{
93	    static uint32_t last_click;
94	    uint32_t now;
95	
96	    (void)event;
97	    home_record_activity();
98	
99	    /* 点击去抖:触摸屏偶尔把一次点击弹成两次 CLICKED(start→立刻 stop,
100	     * 录音只有 1 包,用户感觉"点了没反应")。350ms 内的重复点击忽略。 */
101	    now = lv_tick_get();
102	    if (now - last_click < 350) {
103	        return;
104	    }
105	    last_click = now;
106	
107	    if (!wifi_status_is_connected()) {
108	        return;
109	    }
110	    if (!g_recording) {
111	        g_recording = true;
112	        (void)doubao_voice_start();
113	    } else {
114	        g_recording = false;
115	        (void)doubao_voice_stop();
116	    }
117	}
