150	void ui_voice_refresh(lv_timer_t *timer)
151	{
152	    doubao_voice_snapshot_t snapshot;
153	    bool enabled;
154	
155	    (void)timer;
156	    if (!g_action) return;
157	    doubao_voice_get_snapshot(&snapshot);
158	
159	    /* 新一轮开始:上一轮气泡已沉淀为历史,清空当前轮引用 */
160	    if (snapshot.turn_seq != g_cur_turn) {
161	        g_cur_turn = snapshot.turn_seq;
162	        g_cur_user_bubble = NULL;
163	        g_cur_ai_bubble = NULL;
164	        g_last_user[0] = '\0';
165	        g_last_reply[0] = '\0';
166	    }
167	
168	    if (snapshot.user_text[0] && strcmp(snapshot.user_text, g_last_user) != 0) {
169	        strncpy(g_last_user, snapshot.user_text, sizeof(g_last_user) - 1);
170	        g_cur_user_bubble = set_bubble(g_cur_user_bubble, "你：",
171	                                       snapshot.user_text, true);
172	    }
173	    if (snapshot.assistant_text[0] &&
174	        strcmp(snapshot.assistant_text, g_last_reply) != 0) {
175	        strncpy(g_last_reply, snapshot.assistant_text, sizeof(g_last_reply) - 1);
176	        g_cur_ai_bubble = set_bubble(g_cur_ai_bubble, "豆包：",
177	                                     snapshot.assistant_text, false);
178	    }
179	
180	    lv_label_set_text(g_state_label,
181	                      snapshot.state == DOUBAO_VOICE_ERROR &&
182	                      snapshot.error_text[0] ? snapshot.error_text :
183	                      status_text(snapshot.state));
184	
185	    /* g_recording 与真实状态同步自愈:录音结束(worker 进入 WAITING/PLAYING
186	     * 等非 RECORDING 态)后把本地 toggle 复位,避免下次点击语义颠倒。 */
187	    if (g_recording && snapshot.state != DOUBAO_VOICE_RECORDING &&
188	        snapshot.state != DOUBAO_VOICE_IDLE) {
189	        g_recording = false;
190	    }
191	
192	    enabled = (snapshot.state == DOUBAO_VOICE_IDLE ||
193	               snapshot.state == DOUBAO_VOICE_RECORDING) &&
