205	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x566573), 0);
206	        lv_obj_add_state(g_action, LV_STATE_DISABLED);
207	    } else if (snapshot.state == DOUBAO_VOICE_RECORDING) {
