222	        continue;
223	      }
224	      capturing = true;
225	      memset(window, 0, sizeof(window));   /* 旧窗口作废, 重新积累 1s */
226	      consec = 0;
227	    }
228	    if (mic_capture_read(&cap, hopbuf, WAKE_HOP_SAMPLES) != 0) {
229	      mic_capture_stop(&cap);      /* 读异常: 释放重开 */
230	      capturing = false;
231	      continue;
232	    }
233	
234	    /* 滑动窗口左移 hop, 末尾追加新数据 */
235	    memmove(window, window + WAKE_HOP_SAMPLES,
236	            (MEL_SR - WAKE_HOP_SAMPLES) * sizeof(float));
237	    for (int i = 0; i < WAKE_HOP_SAMPLES; ++i)
238	      window[MEL_SR - WAKE_HOP_SAMPLES + i] = hopbuf[i] / 32768.0f;
239	
240	    mel_compute(window, mel);
241	    predict(mel, p3);
242	    float prob = p3[0];
243	    ++f;
244	
245	    /* 连续 WAKE_CONSEC 窗超阈才判唤醒: 误报多为孤立单窗尖峰,
