247	    if (prob > WAKE_THR) ++consec; else consec = 0;
248	    if (consec >= WAKE_CONSEC && (f - last_wake) >= WAKE_MIN_DIST) {
249	      last_wake = f;
250	      consec = 0;
251	      ++wakes;
